                        },
                        "required": [
                          "type",
                          "item",
                          "perSecond"
                        ]
                      }
                    ]
                  }
                },
                "required": [
                  "kind",
                  "recipe"
                ]
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "source"
                  },
                  "item": {
                    "type": "string",
                    "pattern": "^[a-z0-9][a-z0-9._-]*(@[a-z0-9._-]+)?$"
                  },
                  "maxPerSecond": {
                    "description": "Most this source supplies; unlimited when left out.",
                    "type": "number",
                    "minimum": 0
