                    "const": "port"
                  },
                  "direction": {
                    "type": "string",
                    "enum": [
                      "in",
                      "out"
                    ]
                  },
                  "item": {
                    "type": "string",
                    "pattern": "^[a-z0-9][a-z0-9._-]*(@[a-z0-9._-]+)?$"
                  }
                },
                "required": [
                  "kind",
                  "direction",
                  "item"
                ],
                "description": "A blueprint's boundary."
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "note"
                  },
                  "text": {
                    "type": "string"
                  }
                },
                "required": [
                  "kind",
                  "text"
                ]
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "frame"
