                  "tone": {
                    "type": "string"
                  },
                  "collapsed": {
                    "description": "Folded to its label bar: the canvas hides the nodes it holds and draws their flows to the bar.",
                    "type": "boolean",
                    "const": true
                  }
                },
                "required": [
                  "kind",
                  "label"
                ]
              }
            ]
