          "type": "object",
          "propertyNames": {
            "type": "string",
            "minLength": 1
          },
          "additionalProperties": {
            "type": "object",
            "properties": {
              "from": {
                "type": "string",
                "minLength": 1
              },
              "to": {
                "type": "string",
                "minLength": 1
              },
              "fromPort": {
                "type": "string",
                "minLength": 1
              },
              "toPort": {
                "type": "string",
                "minLength": 1
              },
              "item": {
                "type": "string",
