              },
              "ratio": {
                "description": "Fixed share of the source node's output of this item.",
                "type": "number",
                "minimum": 0,
                "maximum": 1
              }
            },
            "required": [
              "from",
              "to",
              "item"
            ]
          }
        }
      },
      "required": [
        "nodes",
        "edges"
      ]
    },
    "blueprints": {
